// The IC fuzz target (IC3; IC study section 7): GUI.Forms' behavioural
// constraint declarations, run. gf_abi_ic_blocks.hpp (generated by gui_forms
// tools/ic_abi_fuzz.py from the declarations' block stubs) holds one block
// per C ABI call and admitted state (legal) and one per refusal (misuse);
// ic_engine.hpp draws their arguments from the input. The compound blocks
// below are written by hand: the hostile handlers (a subscription's handler
// that disposes or releases its source, or ends its own subscription, while
// the library dispatches to it; a posted callback that disposes its target;
// a drag whose handler destroys the window; a menu whose command destroys
// the menu or the window).
//
// The oracle, per step:
//   - every status is one of the ABI's; never GF_STATUS_WRONG_THREAD (one
//     thread runs everything), and GF_STATUS_INTERNAL or
//     GF_STATUS_NATIVE_EXCEPTION only where the declaration names it;
//   - a misuse block sees exactly the refusal its declaration states, and
//     the subject's state (the public state query: objects.state or
//     windows.lifecycle) is unchanged;
//   - a legal block that succeeds leaves the subject in the state the
//     declaration's `moves` names; one refused with a status the declaration
//     says leaves things unchanged leaves the state where it was;
//   - a status the declaration does not state at all is counted per block
//     and listed at the end: the reconciliation's input (IC3 item 5). With
//     GUI_FORMS_IC_STRICT=1 it is a finding too.
// A finding prints the block and aborts, as a fuzzer's crash does; no crash,
// throw or sanitizer report may happen either.
//
// Built two ways (gui_forms cmake/FuzzTargets.cmake): libFuzzer's entry
// alone, and with GUI_FORMS_FUZZ_STANDALONE the ctest driver below, which
// runs every block once in each mode, each compound block once per action,
// and then a fixed number of pseudo-random programs, deterministically.
// Usage of the standalone program: gui_forms_ic_abi_fuzz_tests [runs].

#include "gf_abi_ic_blocks.hpp"
#include "ic_engine.hpp"

#include "gui_forms/c/gf_abi.h"
#include "gui_forms/component/component/component.hpp"
#include "gui_forms/components/context_menu/context_menu.hpp"
#include "gui_forms/control/control/control.hpp"
#include "gui_forms/control/stable_id/stable_id.hpp"
#include "gui_forms/controls/menu_strip.hpp"
#include "gui_forms/controls/panel.hpp"
#include "gui_forms/controls/split_container.hpp"
#include "gui_forms/controls/split_container_values.hpp"
#include "gui_forms/event/event/event.hpp"
#include "gui_forms/events/input_events/input_events.hpp"
#include "gui_forms/semantics/types/semantic_types.hpp"
#include "gui_forms/types/geometry/geometry.hpp"
#include "gui_forms/types/paint_types/paint_types.hpp"
#include "gui_forms/types/painter/painter.hpp"
#include "gui_forms/window/window.hpp"

